#include <vector>
#include <cstddef>
#include <omp.h>

void gemv(std::vector<double> const& A,
          std::vector<double> const& x,
          std::vector<double> &y,
          size_t M,
          size_t N)
{
    // Assume A has size M*N, x has size N, y has size M.
    // Each thread writes distinct y[i], so no synchronization is needed.
    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(M); ++i) {
        double sum = 0.0;
        const size_t row = static_cast<size_t>(i) * N;
        for (size_t j = 0; j < N; ++j) {
            sum += A[row + j] * x[j];
        }
        y[static_cast<size_t>(i)] = sum;
    }
}
